"""Lexicographically Smallest Equivalent String — union-find keyed by letter.

Union always points at the smaller character, so every root is the smallest
letter of its equivalence class.

Time: O(n * α)   Space: O(1)
"""


class Solution:
    def smallestEquivalentString(self, s1: str, s2: str, baseStr: str) -> str:
        parent = list(range(26))

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        for a, b in zip(s1, s2):
            ra, rb = find(ord(a) - 97), find(ord(b) - 97)
            if ra != rb:
                if ra < rb:
                    parent[rb] = ra
                else:
                    parent[ra] = rb

        return "".join(chr(find(ord(ch) - 97) + 97) for ch in baseStr)
